package cn.zhuatech.customerservice.deep;import cn.zhuatech.customerservice.model.AuditLog;import cn.zhuatech.customerservice.repository.AuditLogRepository;import jakarta.persistence.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Service @Transactional(readOnly=true) public class DeepDomainService{private final EntityManager em;private final AuditLogRepository audits;public DeepDomainService(EntityManager em,AuditLogRepository audits){this.em=em;this.audits=audits;}
 public ServiceDashboard dashboard(String org){List<TicketView> tickets=em.createQuery("select t from ServiceTicket t where t.organizationCode=:o order by t.updatedAt desc",ServiceTicket.class).setParameter("o",org).getResultList().stream().map(this::view).toList();long customers=em.createQuery("select count(c) from Customer c where c.organizationCode=:o and c.active=true",Long.class).setParameter("o",org).getSingleResult(),published=em.createQuery("select count(k) from KnowledgeArticle k where k.organizationCode=:o and k.status='PUBLISHED'",Long.class).setParameter("o",org).getSingleResult(),open=tickets.stream().filter(t->!Set.of("CLOSED","CANCELLED").contains(t.status())).count(),overdue=tickets.stream().filter(t->!Set.of("CLOSED","CANCELLED").contains(t.status())&&t.dueAt().isBefore(LocalDateTime.now())).count();return new ServiceDashboard(tickets,customers,published,open,overdue);}
 @Transactional public CustomerView createCustomer(CustomerRequest r){Customer c=new Customer(r.organizationCode(),r.customerCode(),r.name(),r.level(),r.contactName(),r.contactPhone());em.persist(c);audit("CUSTOMER","创建客户",r.customerCode(),r.name());return view(c);}
 @Transactional public TicketView createTicket(TicketRequest r){Customer c=em.find(Customer.class,r.customerId());if(c==null||!c.organizationCode.equals(r.organizationCode()))throw bad("客户不存在或不属于当前组织");int sla=r.slaMinutes()!=null?r.slaMinutes():switch(r.priority().toUpperCase()){case "P1"->60;case "P2"->240;case "P3"->1440;default->2880;};ServiceTicket t=new ServiceTicket(r.organizationCode(),r.ticketNo(),r.customerId(),r.channel(),r.category(),r.priority().toUpperCase(),r.subject(),r.description(),sla);em.persist(t);audit("TICKET","创建工单",r.ticketNo(),r.subject());return view(t);}
 @Transactional public TicketView assign(Long id,AssignRequest r){ServiceTicket t=ticket(id);if(!Set.of("NEW","ESCALATED","REOPENED").contains(t.status))throw conflict("当前工单不能分派");t.assignee=r.assignee();t.status="ASSIGNED";touch(t);audit("TICKET","分派工单",t.ticketNo,r.assignee());return view(t);}
 @Transactional public MessageView message(Long id,MessageRequest r){ServiceTicket t=ticket(id);if(Set.of("CLOSED","CANCELLED").contains(t.status))throw conflict("终态工单不能新增消息");TicketMessage m=new TicketMessage(id,r.messageType(),r.senderName(),r.content());em.persist(m);if("PUBLIC".equals(r.messageType())&&t.firstResponseAt==null)t.firstResponseAt=m.sentAt;if("NEW".equals(t.status))t.status="IN_PROGRESS";touch(t);audit("TICKET","新增沟通",t.ticketNo,r.messageType());return view(m);}
 @Transactional public TicketView resolve(Long id,ResolveRequest r){ServiceTicket t=ticket(id);if(!Set.of("ASSIGNED","IN_PROGRESS","ESCALATED","REOPENED").contains(t.status))throw conflict("当前工单不能提交解决");long replies=em.createQuery("select count(m) from TicketMessage m where m.ticketId=:id and m.messageType='PUBLIC'",Long.class).setParameter("id",id).getSingleResult();if(replies==0)throw conflict("至少发送一条客户可见回复后才能解决");t.resolution=r.resolution();t.status="RESOLVED";t.resolvedAt=LocalDateTime.now();touch(t);audit("TICKET","提交解决",t.ticketNo,r.resolution());return view(t);}
 @Transactional public TicketView close(Long id){ServiceTicket t=ticket(id);if(!"RESOLVED".equals(t.status))throw conflict("只有已解决工单可以关闭");t.status="CLOSED";t.closedAt=LocalDateTime.now();touch(t);audit("TICKET","客户确认关闭",t.ticketNo,t.resolution);return view(t);}
 @Transactional public TicketView reopen(Long id,ReopenRequest r){ServiceTicket t=ticket(id);if(!"CLOSED".equals(t.status))throw conflict("只有已关闭工单可以重开");if(t.closedAt.plusDays(7).isBefore(LocalDateTime.now()))throw conflict("工单关闭超过7天，请新建服务请求");t.status="REOPENED";t.reopenCount++;t.resolution=null;t.dueAt=LocalDateTime.now().plusMinutes(240);touch(t);audit("TICKET","重开工单",t.ticketNo,r.reason());return view(t);}
 @Transactional public EscalationResult escalate(String org,LocalDateTime asOf){List<ServiceTicket> list=em.createQuery("select t from ServiceTicket t where t.organizationCode=:o and t.status not in('CLOSED','CANCELLED','RESOLVED') and t.dueAt<:at",ServiceTicket.class).setParameter("o",org).setParameter("at",asOf).getResultList();list.forEach(t->{t.status="ESCALATED";touch(t);audit("SLA","工单升级",t.ticketNo,"asOf="+asOf);});return new EscalationResult(list.size(),list.stream().map(this::view).toList());}
 @Transactional public ArticleView createArticle(ArticleRequest r){KnowledgeArticle a=new KnowledgeArticle(r.organizationCode(),r.articleNo(),r.title(),r.category(),r.content(),r.owner());em.persist(a);audit("KNOWLEDGE","创建知识",r.articleNo(),r.title());return view(a);}@Transactional public ArticleView submitArticle(Long id){KnowledgeArticle a=article(id);if(!"DRAFT".equals(a.status))throw conflict("只有草稿知识可以提交");a.status="IN_REVIEW";return view(a);}@Transactional public ArticleView publishArticle(Long id){KnowledgeArticle a=article(id);if(!"IN_REVIEW".equals(a.status))throw conflict("只有待审核知识可以发布");a.status="PUBLISHED";a.publishedAt=LocalDateTime.now();audit("KNOWLEDGE","发布知识",a.articleNo,a.title);return view(a);}public List<ArticleView> searchKnowledge(String org,String keyword){String k="%"+keyword.toLowerCase()+"%";return em.createQuery("select a from KnowledgeArticle a where a.organizationCode=:o and a.status='PUBLISHED' and (lower(a.title) like :k or lower(a.content) like :k) order by a.helpfulCount desc",KnowledgeArticle.class).setParameter("o",org).setParameter("k",k).getResultList().stream().map(this::view).toList();}
 private ServiceTicket ticket(Long id){ServiceTicket t=em.find(ServiceTicket.class,id);if(t==null)throw notFound("工单不存在");return t;}private KnowledgeArticle article(Long id){KnowledgeArticle a=em.find(KnowledgeArticle.class,id);if(a==null)throw notFound("知识文章不存在");return a;}private void touch(ServiceTicket t){t.updatedAt=LocalDateTime.now();}private CustomerView view(Customer c){return new CustomerView(c.id,c.organizationCode,c.customerCode,c.name,c.level,c.contactName,c.contactPhone,c.active);}private TicketView view(ServiceTicket t){long elapsed=t.resolvedAt==null?ChronoUnit.MINUTES.between(t.createdAt,LocalDateTime.now()):ChronoUnit.MINUTES.between(t.createdAt,t.resolvedAt);return new TicketView(t.id,t.organizationCode,t.ticketNo,t.customerId,t.channel,t.category,t.priority,t.subject,t.status,t.assignee,t.createdAt,t.dueAt,t.firstResponseAt,t.resolvedAt,t.reopenCount,elapsed,t.version);}private MessageView view(TicketMessage m){return new MessageView(m.id,m.ticketId,m.messageType,m.senderName,m.content,m.sentAt);}private ArticleView view(KnowledgeArticle a){return new ArticleView(a.id,a.articleNo,a.title,a.category,a.status,a.owner,a.helpfulCount,a.publishedAt,a.version);}private void audit(String m,String a,String n,String d){audits.save(new AuditLog(m,a,n,"domain-service",d));}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
 public record CustomerRequest(@NotBlank String organizationCode,@NotBlank String customerCode,@NotBlank String name,@NotBlank String level,@NotBlank String contactName,@NotBlank String contactPhone){}public record TicketRequest(@NotBlank String organizationCode,@NotBlank String ticketNo,@NotNull Long customerId,@NotBlank String channel,@NotBlank String category,@Pattern(regexp="P[1-4]")String priority,@NotBlank String subject,@NotBlank String description,@Positive Integer slaMinutes){}public record AssignRequest(@NotBlank String assignee){}public record MessageRequest(@Pattern(regexp="PUBLIC|INTERNAL")String messageType,@NotBlank String senderName,@NotBlank @Size(max=2000)String content){}public record ResolveRequest(@NotBlank String resolution){}public record ReopenRequest(@NotBlank String reason){}public record ArticleRequest(@NotBlank String organizationCode,@NotBlank String articleNo,@NotBlank String title,@NotBlank String category,@NotBlank @Size(max=5000)String content,@NotBlank String owner){}
 public record CustomerView(Long id,String organizationCode,String customerCode,String name,String level,String contactName,String contactPhone,boolean active){}public record TicketView(Long id,String organizationCode,String ticketNo,Long customerId,String channel,String category,String priority,String subject,String status,String assignee,LocalDateTime createdAt,LocalDateTime dueAt,LocalDateTime firstResponseAt,LocalDateTime resolvedAt,int reopenCount,long elapsedMinutes,long version){}public record MessageView(Long id,Long ticketId,String messageType,String senderName,String content,LocalDateTime sentAt){}public record ArticleView(Long id,String articleNo,String title,String category,String status,String owner,int helpfulCount,LocalDateTime publishedAt,long version){}public record EscalationResult(int escalated,List<TicketView> tickets){}public record ServiceDashboard(List<TicketView> tickets,long activeCustomers,long publishedArticles,long openTickets,long overdueTickets){}
}
